pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Setup: give caller 2 ether
        address caller = address(0x1234);
        vm.deal(caller, 2 ether);

        // Step 1: caller deposits 2 ether (which is > MinDeposit = 1 ether)
        vm.prank(caller);
        c.Deposit{value: 2 ether}();

        // Step 2: caller cashes out all 2 ether
        vm.prank(caller);
        c.CashOut(2 ether);

        // After cashout, in reference: balances[caller] = 0; in buggy: balances[caller] = 2 ether
        // Now caller tries to deposit another 2 ether (again > MinDeposit).
        vm.deal(caller, 2 ether);
        vm.prank(caller);
        c.Deposit{value: 2 ether}();

        // Check if the deposit actually increased the caller's balance.
        // In the reference, after the second deposit, the balance should be 2 ether (since old balance was 0, +2 = 2).
        // In the buggy, after the second deposit, the balance should be 4 ether (since old balance was still 2, +2 = 4).
        // But both cases pass the overflow check, so they both succeed.
        // Instead, we need a different divergence: the buggy contract sends ether twice without deducting.
        // A better approach: check that after cashout, the caller's balance is correct.
        // After step 2, reference: balances[caller] = 0; buggy: balances[caller] = 2 ether.
        // Now, caller attempts a third deposit of exactly 0.5 ether (below MinDeposit) — this should fail in both.
        // Not good.
        // Simpler: check address(c).balance reduction? Not reliable due to reentrancy.
        // Let's use a simple assertion: after cashout, the caller's balance in the reference is 0.
        // But the test must pass on reference and fail on buggy.
        // Since we have no getter for private state, we check the effect: if caller tries to cashout again with same amount.
        // In reference, 2 ether <= 0 is false, so CashOut does nothing (no revert, just skip).
        // In buggy, 2 ether <= 2 ether is true, so it sends ether again (double spend).
        bool success;
        vm.prank(caller);
        try c.CashOut(2 ether) { success = true; } catch { success = false; }
        // Reference: CashOut does nothing (skip), so no revert, success = true.
        // Buggy: CashOut sends ether, success = true, then no revert.
        // Both return true, no divergence here.
        // Need a different approach: check that after step2, the caller's balance is 0 in reference.
        // Since there's no getter, we can check the deposit condition again.
        // After step2, caller has 0 balance in reference, so trying to deposit exactly 1 ether (==MinDeposit)
        // will NOT increase balance because condition is > MinDeposit, not >=.
        // So both remain 0. Not good.
        // Let's check the total ether sent to the Log contract? No.
        // The only way to observe balance without getter is to see if deposit condition (msg.value > MinDeposit)
        // triggers. But that's independent.
        // Actually, we can check balances[caller] via the auto-generated getter.
        // The contract has: mapping (address => uint) public balances;
        // So c.balances(caller) is valid.
        uint256 balanceAfterCashout = c.balances(caller);
        // Reference: 0; Buggy: 2 ether
        assertTrue(balanceAfterCashout == 0, "Balance should be 0 after cashout");
    }
}

